editorialMd:
Build the result list

Find the middle node of the linked list given by head. Each node stores a number in val and a link in next. Use two pointers: one moves one link at a time, and the other moves two. If there are two middle nodes, choose the second one. Record the values from that middle node to the end. An empty list gives an empty result list.

Return the answer

Count the even numbers in the result list. An even number divides by 2 with no remainder. Count 0 and negative even numbers too. Return the count. An empty list gives 0.

Why this works

Each value in the result list follows Step 1. Step 2 uses only those values. Keeping these steps separate helps avoid returning the list when the question asks for one number. Check empty input, one item, repeated values, and the largest allowed input.

Efficiency goal: time O(n); extra memory, including the result list, O(n). n is the number of nodes. These labels describe how work and memory grow with the input.

javascript
function midpointChainEvenKeyCensus(head, k) {
  const a=head; let out=[];
  let slow=a,fast=a;while(fast&&fast.next){slow=slow.next;fast=fast.next.next;}for(let node=slow;node;node=node.next)out.push(node.val);
  return out.filter(x=>x%2===0).length;
}


typescript
type ListNode = { val: number; next: ListNode | null };
function midpointChainEvenKeyCensus(head: ListNode | null, k: number): number {
  const a=head; let out:number[]=[];
  let slow=a,fast=a;while(fast&&fast.next){slow=slow!.next;fast=fast.next.next;}for(let node=slow;node;node=node.next)out.push(node.val);
  return out.filter(x=>x%2===0).length;
}


python
def midpointChainEvenKeyCensus(head, k):
    a=head
    out=[]
    slow=fast=a
    while fast and fast.next:
        slow=slow.next
        fast=fast.next.next
    node=slow
    while node:
        out.append(node.val)
        node=node.next
    return sum(x%2==0 for x in out)


java
class Solution {
  public int midpointChainEvenKeyCensus(ListNode head, int k) {
    ListNode a=head; List<Integer> out=new ArrayList<>();
    {ListNode slow=a,fast=a;while(fast!=null&&fast.next!=null){slow=slow.next;fast=fast.next.next;}for(ListNode node=slow;node!=null;node=node.next)out.add(node.val);}
    int answer=0;for(int x:out)if(x%2==0)answer++;return answer;
  }
}
